/* Generated by `ko-agent-fs --bpf-records-header` from src/bpf_records.rs, which has the file
 * format; a test compares this file with the generator. The map records of the BPF cgroup-LSM
 * backend, as the guard writes them and the controller loads them (bpf/ko-agent-bpf/doc/architecture.md,
 * "The policy"), in native byte order. The types are the kernel's: include this after vmlinux.h
 * in a program, after <linux/types.h> in user space. */
#ifndef KO_AGENT_FS_RECORDS_H
#define KO_AGENT_FS_RECORDS_H

#define RECORDS_MAGIC "KOFSBPF1"
#define RECORDS_LAYOUT 0x863db990u

#define RULE_LINES 128
#define RULE_COMPS 7      /* bit k of a partial byte: the line's first k components matched */
#define COMP_BYTES 64
#define ALIASES 16
#define ROOTS 64
#define GUARDED_PATHS 62   /* the rest of ROOTS is the controller's: fixture and volume */
#define PATH_BYTES 4096

enum rule_word {
	WORD_READ_ONLY = 1,
	WORD_WRITABLE = 2,
	WORD_PINNED = 3,
};

enum root_kind {
	/* a workspace root, or the proof fixture's: the walk's position is NotGit */
	ROOT_WORKSPACE = 1,
	/* a gitdir the guard found under .git/modules: the position is InGit([]) */
	ROOT_GITDIR = 2,
	/* the persistent volume's root, the controller's own: the socket rule alone */
	ROOT_VOLUME = 3,
	/* a .git object, the root's or a submodule worktree's pointer file: any name is the gitdir entry */
	ROOT_GUARDED_GIT = 4,
	/* the root's .ko-agent-sandbox object: any name is the launcher's directory */
	ROOT_GUARDED_SANDBOX = 5,
};

struct records_header {
	char magic[8];
	__u32 layout;
	__u32 rule_count;
	__u32 alias_count;
	__u32 root_count;
};

/* One resolved rule line, folded by the guard. `alias` names the alias context (1-based) the line's
 * end activates, for an anchored pinned-path line at the end of a symlink the guard followed; 0 is
 * none. */
struct rule_line {
	__u8 word;
	__u8 anchored;
	__u8 ncomp;
	__u8 alias;
	char comp[RULE_COMPS][COMP_BYTES];
};

/* The rule context of the symlink whose end a pinned-path line names: what every entry below that
 * end also stands as (policy.rs, FileRules::push_alias). `deciding` is -1 for none. */
struct alias_context {
	__u8 partial[RULE_LINES];
	__s32 deciding;
	__u32 pinned_path;
};

/* A guarded object by workspace-relative path, empty for the root itself; the controller records
 * its identity with statx. */
struct guarded_path {
	__u32 kind;
	__u32 len;
	char path[PATH_BYTES];
};

_Static_assert(sizeof(struct records_header) == 24, "records_header");
_Static_assert(sizeof(struct rule_line) == 452, "rule_line");
_Static_assert(sizeof(struct alias_context) == 136, "alias_context");
_Static_assert(sizeof(struct guarded_path) == 4104, "guarded_path");

#endif
